import java.util.Arrays;
import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.model.Element;
import org.joget.apps.form.model.Form;
import org.joget.apps.form.model.FormData;
import org.joget.apps.form.service.FormUtil;
 
public boolean validate(Element element, FormData formData, String[] values) {
    boolean result = true;
 
    //get field 1 value from form data object
    String field1Id = "nouveau_mdp";
    Form form = FormUtil.findRootForm(element);
    Element field1 = FormUtil.findElement(field1Id, form, formData);
 
    if (field1 != null) {
        //get value of field 1
        String[] compareValues = FormUtil.getElementPropertyValues(field1, formData);
 
        //compare the value of field 2 and field 1 are equals
        if (!Arrays.equals(values, compareValues)) {
            String id = FormUtil.getElementParameterName(element);
            formData.addFormError(id, "Vérifier si les mots de passes sont identiques");
            result = false;
        }
    } else {
        //ignore if the field 1 not exist
    }
 
    return result;
}
 
//call validate method with injected variable
return validate(element, formData, values);

import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.model.*;
import org.joget.commons.util.LogUtil;
import org.joget.commons.util.StringUtil;
import org.joget.commons.util.UuidGenerator;
import org.joget.directory.dao.EmploymentDao;
import org.joget.directory.dao.UserDao;
import org.joget.directory.model.*;
import org.joget.directory.model.service.DirectoryManager;

        // Generate a new UUID
        String pId = UuidGenerator.getInstance().getUuid();

        // Get UserDao and DirectoryManager beans
        UserDao userDao = (UserDao) AppUtil.getApplicationContext().getBean("userDao");
        DirectoryManager dm = (DirectoryManager) AppUtil.getApplicationContext().getBean("directoryManager");

        // Retrieve the current user
        User user = dm.getUserByUsername("#currentUser.username#");

        // Log and update the user password
        String password = "#form.edit_profil.nouveau_mdp#";
        LogUtil.info("Password entered ---> ", password);
        String encodedPassword = StringUtil.md5Base16(password);
        LogUtil.info("Encoded password ---> ", encodedPassword);
        user.setPassword(encodedPassword);
        userDao.updateUser(user);

        // Assign the user to an employment role
        EmploymentDao employmentDao = (EmploymentDao) AppUtil.getApplicationContext().getBean("employmentDao");
        Employment emp = new Employment();
        emp.setId(pId);
        emp.setUserId(user.getId());

        if (userDao.unassignUserFromGroup(user.getId(), "first_login_etab")) {
            LogUtil.info("Employment added ---> ", String.valueOf(employmentDao.addEmployment(emp)));
        

        }
